```javascript
const axios = require("axios");

async function getData(input) {
  try {
    const response = await axios.post(
      "https://api.snapany.com/v1/extract/subtitles",
      {
        url: input
      },
      {
        headers: {
          "Content-Type": "application/json"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://youtu.be/Ys7-6_t7OEQ?si=iQdzNlOaD0REbHkg")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
